<?php
require_once dirname(__DIR__).'/session_bootstrap.php';$ttCallToken=(string)($_SERVER['HTTP_X_TABLETIME_CALL_TOKEN']??($_REQUEST['auth_token']??''));if((empty($_SESSION['loggedin'])||empty($_SESSION['id']))&&$ttCallToken!=='')tt_restore_call_api_token($ttCallToken);if(empty($_SESSION['loggedin'])||empty($_SESSION['id'])){header('Content-Type: application/json; charset=utf-8');http_response_code(401);echo json_encode(['error'=>'login_required','count'=>0,'calls'=>[]]);exit;}require_once dirname(__DIR__).'/core.php';header('Content-Type: application/json; charset=utf-8');$db=tt_db_open(true);$uid=(int)$_SESSION['id'];$me=(string)$_SESSION['name'];$rows=[];$r=$db->query("SELECT c.call_key,c.scope_type,c.title,c.members,c.created_by,c.updated_at,EXISTS(SELECT 1 FROM call_participants p WHERE p.call_id=c.id AND p.account_id=".$uid." AND p.left_at IS NULL AND p.last_seen_at>UTC_TIMESTAMP()-INTERVAL 60 SECOND) joined FROM calls c WHERE c.status='open' AND c.updated_at>UTC_TIMESTAMP()-INTERVAL 30 MINUTE ORDER BY c.updated_at DESC LIMIT 60");if($r){while($x=$r->fetch_assoc()){if(in_array($me,tt_member_list((string)$x['members']),true)||(int)$x['created_by']===$uid)$rows[]=['call_key'=>$x['call_key'],'scope_type'=>$x['scope_type'],'title'=>$x['title'],'joined'=>(bool)$x['joined'],'mine'=>(int)$x['created_by']===$uid];}$r->free();}$db->close();echo json_encode(['ok'=>true,'count'=>count($rows),'calls'=>array_slice($rows,0,10)],JSON_UNESCAPED_SLASHES);
